<?php
namespace App\Http\Controllers\Api\V1;
use App\Models\{Tenant,TenantSubscription}; use App\Services\{AuthorizationService,SubscriptionService}; use App\Support\TenantContext; use Illuminate\Http\Request;
final class TenantSubscriptionController { public function show(SubscriptionService $service){$tenant=Tenant::findOrFail(app(TenantContext::class)->id());return response()->json(['data'=>$service->active($tenant)]);} public function change(Request $r,SubscriptionService $service,AuthorizationService $auth){$t=app(TenantContext::class)->id();abort_unless($auth->allows($r->user(),$t,'organization.manage'),403);$d=$r->validate(['plan_id'=>'required|uuid','billing_cycle'=>'required|in:monthly,annual']);return response()->json(['data'=>$service->changePlan($t,$d['plan_id'],$d['billing_cycle'])]);} public function cancel(Request $r,SubscriptionService $service,AuthorizationService $auth){$t=app(TenantContext::class)->id();abort_unless($auth->allows($r->user(),$t,'organization.manage'),403);return response()->json(['data'=>$service->cancel($t)]);}}
